import 'dart:convert';\n\nimport 'package:http/http.dart' as http;\n\nclass AurenGaezV5Service {\n  static const String readmeUrl =\n      'https://data.apps.fao.org/catalog/dataset/514c92d5-9e01-4c70-814a-80ea1ca9fe6a/resource/768b08ad-be9c-427a-84be-3a3d6dd7835a/download/_readme_res05.xlsx';\n\n  static const String baseUrl =\n      'https://storage.googleapis.com/fao-gismgr-gaez-v5-data/DATA/GAEZ-V5/MAPSET';\n\n  String buildRasterUrl({\n    required String mapset,\n    required String period,\n    required String climate,\n    required String scenario,\n    required String crop,\n    required String input,\n  }) {\n    final parts = <String>[mapset, period, climate, scenario, crop, input]\n        .map((v) => v.trim().toUpperCase()).toList();\n    if (parts.any((value) => value.isEmpty)) {\n      throw ArgumentError('GAEZ v5 dataset dimensions are required.');\n    }\n    final fileName = 'GAEZ-V5.' + parts.join('.');\n    return baseUrl + '/' + Uri.encodeComponent(parts[0]) + '/' +\n        Uri.encodeComponent(fileName) + '.tif';\n  }\n\n  Future<bool> exists({\n    required String mapset, required String period, required String climate,\n    required String scenario, required String crop, required String input,\n    http.Client? client,\n  }) async {\n    final url = buildRasterUrl(mapset: mapset, period: period, climate: climate,\n        scenario: scenario, crop: crop, input: input);\n    final c = client ?? http.Client();\n    try {\n      final response = await c.head(Uri.parse(url));\n      return response.statusCode == 200;\n    } finally {\n      if (client == null) c.close();\n    }\n  }\n\n  Map<String, dynamic> describe({\n    required String mapset, required String period, required String climate,\n    required String scenario, required String crop, required String input,\n  }) => {\n    'source': 'FAO/IIASA GAEZ v5', 'resource': 'RES05',\n    'mapset': mapset, 'period': period, 'climate': climate,\n    'scenario': scenario, 'crop': crop, 'input': input,\n    'url': buildRasterUrl(mapset: mapset, period: period, climate: climate,\n        scenario: scenario, crop: crop, input: input),\n  };\n\n  Map<String, dynamic> historicalCropDataset({\n    required String crop, String input = 'HRLM',\n  }) => describe(mapset: 'RES05-ETL', period: 'HP0120', climate: 'AGERA5',\n      scenario: 'HIST', crop: crop, input: input);\n\n  static Map<String, dynamic> decodeJsonMap(String body) {\n    final decoded = jsonDecode(body);\n    if (decoded is! Map<String, dynamic>) {\n      throw const FormatException('Expected a JSON object.');\n    }\n    return decoded;\n  }\n}